function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5500);}
function status(){const stale=project.manifest!==newProject().manifest;$('#save-state').textContent=storageError?'● Unsaved · export a copy':stale?'● Source snapshot differs':dirty?'● Unsaved':'● Saved on this device';$('#save-state').className=storageError||stale?'warning':'';$('#save-state').title=storageError||'Local browser storage. Export a portable copy.';}
function save(){dirty=true;try{if(loadBlocked)throw Error('Saved board could not be read. Open storage recovery before saving.');project=saveProject(localStorage,KEY,project,expected);expected=project.revision;storageError='';dirty=false;}catch(e){storageError=e.message;toast(e.message);}status();}
function checkpoint(){history.push(JSON.stringify(project));if(history.length>40)history.shift();future=[];}
function change(fn){checkpoint();fn();save();render();}
function record(){return project.records.find(r=>r.id===selected)||project.records[0];}
function select(id,remember=true){if(!project.records.some(r=>r.id===id))return;if(remember&&selected!==id)back.push(selected);selected=id;model?.select(id);renderCards();renderInspector();renderOutline();const heading=$('#inspector h2');heading.tabIndex=-1;heading.focus({preventScroll:true});$('#inspector').scrollTop=0;}
function lines(){
 const filter=$('#line-filter').value;
 const rect=id=>{if(id==='vision'){const el=$('#model-card');return {x:el.offsetLeft,y:el.offsetTop,w:el.offsetWidth,h:el.offsetHeight};}const r=project.records.find(n=>n.id===id);const el=$(`[data-id="${id}"]`);return r?{x:r.x,y:r.y,w:300,h:el?.offsetHeight||200}:null;};
 const shown=project.edges.filter(e=>filter==='all'||filter==='selected'&&(e.from===selected||e.to===selected));
 $('#connections').innerHTML='<defs><marker id="edge-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>'+shown.map(e=>{const a=rect(e.from),b=rect(e.to);if(!a||!b)return '';const {path,mid,start}=connectionGeometry(a,b),label=edgeLabel(e),from=project.records.find(r=>r.id===e.from),to=project.records.find(r=>r.id===e.to);return `<g class="edge" tabindex="0" role="button" data-edge="${esc(e.id)}" aria-label="${esc(displayText(from,'title')+' '+label+' '+displayText(to,'title'))}"><path class="edge-hit" d="${path}"/><path class="edge-line" d="${path}" marker-end="url(#edge-arrow)"/><circle cx="${start.x}" cy="${start.y}" r="3"/><rect x="${mid.x-label.length*3.5-10}" y="${mid.y-11}" width="${label.length*7+20}" height="22" rx="5"/><text x="${mid.x}" y="${mid.y+4}" text-anchor="middle">${esc(label)}</text></g>`;}).join('');
 $('#section-frames').innerHTML=sections.map(section=>{const b=sectionBounds(project.records,section.id);return b?`<section class="board-section section-${section.id}" style="left:${b.x}px;top:${b.y}px;width:${b.w}px;height:${b.h}px" aria-label="${section.title}"><div class="board-section-heading" data-drag-section="${section.id}" tabindex="0" role="button" aria-label="Move ${section.title} cards. Drag or use arrow keys."><span>${section.number}</span><div><h2>${section.title}</h2><p>${section.subtitle}</p></div><span class="section-count">⠿ Drag cards</span></div></section>`:'';}).join('');
}

function renderCards(){$('#cards').innerHTML=project.records.filter(r=>r.id!=='vision').map(r=>`<article class="card ${r.type} ${r.id===selected?'selected':''}" style="left:${r.x}px;top:${r.y}px" data-id="${esc(r.id)}"><button tabindex="-1" class="card-handle" data-select="${esc(r.id)}" aria-label="Select ${esc(displayText(r,'title'))}"><span class="card-type"><span>${icons[r.type]}</span> ${r.type.toUpperCase()}</span><span class="card-grip">⠿</span></button><button tabindex="-1" class="card-content" data-select="${esc(r.id)}"><h2>${esc(displayText(r,'title'))}</h2><p>${esc(displayText(r,'summary'))}</p><span class="card-bottom"><span class="claim">${esc(r.claim==='proposal'?'PROPOSED':r.claim==='concept'?'CONCEPT':r.claim==='unknown'?'OPEN':r.claim)}</span><span>${project.edges.filter(e=>e.from===r.id||e.to===r.id).length} connections ↗</span></span></button></article>`).join('');lines();paintGroup();}
function readingPath(r){const step=contextStep(r),proposal=step.proposal?`<p class="draft-next"><strong>Draft next step:</strong> ${esc(step.proposal)}</p>`:'';return `<section class="reading-path" aria-label="Context and next step">${step.label?`<div class="status-label">${esc(step.label)}</div>`:''}${step.explain?`<p>${esc(step.explain)}</p>`:''}${proposal}<nav aria-label="Suggested next step">${step.back?`<button data-read="${step.back}" class="quiet-action">← Back</button>`:''}${step.next?`<button data-read="${step.next}" class="primary">${esc(step.action||'Continue')} →</button>`:''}${step.draft?`<button data-draft class="primary">${esc(step.draftLabel||'Draft the gap')} →</button>`:''}</nav><details class="more-paths"><summary>More places to explore</summary><div><button data-read="vision">Project idea</button><button data-read="baseline">Development options</button><button data-read="evidence">Evidence status</button><button data-read="gate">What needs deciding</button></div></details></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-read]');if(b){select(b.dataset.read);focusSelected();}});
function renderInspector(){const r=record(),related=project.edges.filter(e=>e.from===r.id||e.to===r.id),criteria=r.id==='vision-source'?`<section class="human-criteria" aria-labelledby="human-criteria-title"><div class="section-label" id="human-criteria-title">HUMAN CRITERIA</div><p>What the team said the project should achieve:</p><ul>${humanCriteria.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></section>`:'';$('#inspector').innerHTML=`<div class="inspector-top"><span>A CLOSER LOOK</span><button id="toggle-details" aria-label="Toggle details">−</button></div><div class="inspector-body"><div class="detail-type">${icons[r.type]} ${esc(r.type.toUpperCase())}</div><h2>${esc(displayText(r,'title'))}</h2><p class="detail-lead">${esc(displayText(r,'summary'))}</p>${readingPath(r)}${criteria}<details class="record-details"><summary>Full record and tools</summary><div class="divider"></div><div class="section-label">${({concept:'THE IDEA',module:'WHAT IT DOES',question:'THE QUESTION',hypothesis:'WHAT WE ASSUME',experiment:'THE TEST PLAN',decision:'WHY THIS CHOICE?',source:'WHERE THIS CAME FROM',evidence:'WHAT THIS TELLS US',milestone:'BEFORE WE MOVE ON'})[r.type]}</div><p class="detail-text">${esc(displayText(r,'detail'))}</p>${r.id==='wing'?'<div class="mini-spec"><div><strong>2</strong><span>internal wings</span></div><div><strong>3–4<span> ft</span></strong><span>aspirational deployed span</span></div></div>':''}<div class="detail-actions"><button id="pin">${pin===r.id?'Unpin':'Pin to compare'}</button>${!r.locked?'<button id="edit">Edit card ↗</button>':'<span class="source-lock">Source record</span>'}</div>${r.source?`<button class="source-link" data-select="${esc(r.source)}">↗ Read the source</button>`:''}${r.url?`<button class="source-link" data-source-reader="${esc(r.id)}">↗ Read source document</button>`:''}
<div class="section-label connections-title">CONNECTED IDEAS <span>${related.length}</span></div><div class="related">${related.length?related.map(e=>{const id=e.from===r.id?e.to:e.from,t=project.records.find(n=>n.id===id);return `<div class="related-row"><button data-select="${esc(id)}"><span class="relation-verb">${esc(displayText(project.records.find(n=>n.id===e.from),'title')+' '+edgeLabel(e)+' '+displayText(project.records.find(n=>n.id===e.to),'title'))}</span><span>${esc(displayText(t,'title'))} ↗</span></button><button class="remove-edge" data-remove-edge="${esc(e.id)}" aria-label="Remove ${esc(e.verb)} connection">×</button></div>`;}).join(''):'<p class="empty">No relationships recorded.</p>'}</div><button class="wide-dashed" id="connect-here">＋ Connect an idea</button>
<details class="arrange"><summary>Arrange & present</summary><div class="move-buttons"><button id="move-left" data-move="-30,0" aria-label="Move card left">←</button><button id="move-up" data-move="0,-30" aria-label="Move card up">↑</button><button id="move-down" data-move="0,30" aria-label="Move card down">↓</button><button id="move-right" data-move="30,0" aria-label="Move card right">→</button></div><button id="story-add">${project.story.includes(r.id)?'Remove from story':'Add to story'}</button><button id="starter-layout">Restore starter layout</button>${!r.locked?'<button id="delete" class="danger">Delete proposal</button>':''}</details></details>${pin&&pin!==r.id?`<div class="pinned"><div class="section-label">PINNED COMPARISON <button id="unpin">×</button></div><h3>${esc(project.records.find(n=>n.id===pin)?.title||'')}</h3><p>${esc(project.records.find(n=>n.id===pin)?.summary||'')}</p></div>`:''}<div class="inspector-foot"><span class="live-dot"></span> Still a concept, not build-ready.<br><span>Dimensions and test plans still need review.</span></div></div>`;
 $('#toggle-details').onclick=()=>$('#inspector').classList.toggle('collapsed');$('#pin').onclick=()=>{pin=pin===r.id?null:r.id;renderInspector();};if($('#unpin'))$('#unpin').onclick=()=>{pin=null;renderInspector();};if($('#edit'))$('#edit').onclick=()=>editDialog(r);$('#connect-here').onclick=connectDialog;if($('[data-draft]'))$('[data-draft]').onclick=()=>editDialog(null,contextStep(r).draftType||'question');
 $('#story-add').onclick=()=>{if(!project.story.includes(r.id)&&project.story.length>=5)return toast('Your story has five stops. Remove one before adding another.');change(()=>project.story=project.story.includes(r.id)?project.story.filter(i=>i!==r.id):[...project.story,r.id]);};$('#starter-layout').onclick=()=>change(()=>{organizeBoard(project.records);project.layoutVersion=3;});
 if($('#delete'))$('#delete').onclick=()=>{if(seedRecords.some(n=>n.id===r.id))return toast('Starter proposals stay in the board. You can edit their text.');dialog(`<h2>Delete this proposal?</h2><p>This removes “${esc(displayText(r,'title'))}” and its ${related.length} connections. Other records stay. You can undo this change.</p><button class="primary" id="confirm-delete">Delete proposal</button>`);$('#confirm-delete').onclick=()=>{change(()=>{project.records=project.records.filter(n=>n.id!==r.id);project.edges=project.edges.filter(e=>e.from!==r.id&&e.to!==r.id);project.story=project.story.filter(id=>id!==r.id);selected='vision';if(pin===r.id)pin=null;});$('#dialog').close();};};
}
function renderOutline(){$('#outline-list').innerHTML=project.records.filter(r=>matchesRecord(r,query)).map(r=>`<button class="outline-item ${r.id===selected?'active':''}" data-outline="${esc(r.id)}"><span>${icons[r.type]}</span><span>${esc(displayText(r,'title'))}<small>${r.type} · ${r.claim}</small></span></button>`).join('')||'<p class="empty">No matching records.</p>';}
function view(){$('#viewport').scrollTop=0;$('#viewport').scrollLeft=0;const v=project.view;$('#viewport').classList.toggle('exploring',v.y<130||mode==='inspect');$('#world').style.transform=`translate(${v.x}px,${v.y}px) scale(${v.z})`;$('#zoom-label').textContent=Math.round(v.z*100)+'%';}
function render(){const focusId=document.activeElement?.id;const arrangeOpen=$('.arrange')?.open;renderCards();renderInspector();renderOutline();view();status();$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;if(arrangeOpen&&$('.arrange'))$('.arrange').open=true;if(focusId&&document.getElementById(focusId))document.getElementById(focusId).focus({preventScroll:true});}
let dialogTrigger;function dialog(content){if(!$('#dialog').open)dialogTrigger=document.activeElement;$('#dialog').innerHTML=`<button class="dialog-close" aria-label="Close dialog">×</button>${content}`;$('#dialog .dialog-close').onclick=()=>$('#dialog').close();if(!$('#dialog').open)$('#dialog').showModal();}$('#dialog').addEventListener('close',()=>{if(dialogTrigger?.isConnected)dialogTrigger.focus();else $('#add').focus();});
function entryDisclaimer(){
 const entry=$('#dialog');
 entry.classList.add('entry-disclaimer');
 entry.setAttribute('closedby','none');
 entry.addEventListener('keydown',e=>{if(entry.classList.contains('entry-disclaimer')&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();}});
 entry.setAttribute('aria-labelledby','entry-warning-title');
 entry.innerHTML=`<div class="warning-label">IMPORTANT: READ BEFORE ENTERING</div><h2 id="entry-warning-title">THIS IS ONLY AN IDEABOARD.</h2><p class="warning-main">THIS IS NOT HOW A ROCKET WORKS.</p><p class="warning-main">RIGHT NOW, THIS PROBABLY WON’T WORK.</p><p class="warning-context">What follows is an early visual concept full of unanswered questions. It is not a working design, simulation, build guide, or proof that any part will fly.</p><button id="enter-board" class="primary">I understand · Enter the ideaboard</button>`;
 entry.addEventListener('cancel',e=>{if(entry.classList.contains('entry-disclaimer'))e.preventDefault();});
 $('#enter-board').textContent='Okay, I understand';
 $('#enter-board').onclick=()=>entry.close();
 entry.showModal();
}
$('#dialog').addEventListener('close',()=>{$('#dialog').classList.remove('entry-disclaimer');$('#dialog').removeAttribute('aria-labelledby');$('#dialog').removeAttribute('closedby');});
function editDialog(r,suggestedType='question'){dialog(`<div class="eyebrow">${r?'EDIT':'NEW'} LOCAL PROPOSAL</div><h2>${r?'Edit project record':'Add it to your board'}</h2><form id="edit-form"><label>What kind of idea?<select name="type" ${r?'disabled':''}>${['question','hypothesis','experiment','decision'].map(t=>`<option ${r?.type===t||!r&&suggestedType===t?'selected':''} value="${t}">${({question:'Open question',hypothesis:'Possible answer',experiment:'Test to try',decision:'Draft decision'})[t]}</option>`).join('')}</select></label><label>Short title<input name="title" required maxlength="100" value="${esc(r?.title||'')}" placeholder="What do we want to understand?"></label><label>One-line summary<input name="summary" maxlength="220" value="${esc(r?.summary||'')}" placeholder="The idea at a glance"></label><label>Notes<textarea name="detail" rows="5" maxlength="12000" placeholder="Assumptions, sources, next steps…">${esc(r?.detail||'')}</textarea></label><p class="form-hint">This stays an unreviewed local proposal. It saves automatically in this browser. Download a board backup from Project when you want a portable copy.</p><button class="primary" type="submit">${r?'Save changes':'Add to board'} ↗</button></form>`);$('#edit-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),id=r?.id||'local-'+crypto.randomUUID();change(()=>{if(r){r.title=data.get('title');r.summary=data.get('summary');r.detail=data.get('detail');}else project.records.push({id,type:data.get('type'),title:data.get('title'),summary:data.get('summary'),detail:data.get('detail'),claim:'proposal',locked:false,x:record().x+80,y:record().y+220});selected=id;});$('#dialog').close();focusSelected();toast('Idea saved in this browser. Download a backup from Project when you need one.');};}
function captureDialog(){dialog('<div class="eyebrow">ADD TO YOUR LOCAL BOARD</div><h2>What are you adding?</h2><p>Pick the closest fit. You can connect it to another card after saving.</p><div class="capture-types"><button data-new-type="question"><strong>Open question</strong><span>Something we need to learn</span></button><button data-new-type="hypothesis"><strong>Possible answer</strong><span>A guess worth checking</span></button><button data-new-type="experiment"><strong>Test to try</strong><span>How we could get evidence</span></button><button data-new-type="decision"><strong>Draft decision</strong><span>A choice that still needs review</span></button></div><p class="form-hint">Ideas autosave on this device. Project → Download board backup makes a portable copy.</p>');document.querySelectorAll('[data-new-type]').forEach(button=>button.onclick=()=>editDialog(null,button.dataset.newType));}
function connectDialog(){dialog(`<div class="eyebrow">BUILD A RELATIONSHIP</div><h2>Define a relationship</h2><form id="edge-form"><label>Relationship<select id="verb" name="verb">${Object.entries(verbs).map(([v,p])=>`<option value="${v}">${p[0]} ${v} ${p[1]}</option>`).join('')}</select></label><label>From<select id="edge-from" name="from"></select></label><label>To<select id="edge-to" name="to"></select></label><button class="primary">Add connection ↗</button></form>`);const populate=()=>{const pair=verbs[$('#verb').value];for(const [i,id] of ['edge-from','edge-to'].entries())$('#'+id).innerHTML=project.records.filter(r=>r.type===pair[i]).map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(displayText(r,'title'))}</option>`).join('');};const matching=Object.entries(verbs).find(([,pair])=>pair[0]===record().type);if(matching)$('#verb').value=matching[0];populate();$('#verb').onchange=populate;$('#edge-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),edge={id:crypto.randomUUID(),from:d.get('from'),to:d.get('to'),verb:d.get('verb')};if(!edge.from||!edge.to)return;if(project.edges.some(x=>x.from===edge.from&&x.to===edge.to&&x.verb===edge.verb))return toast('That connection already exists.');change(()=>project.edges.push(edge));$('#dialog').close();};}
function focusSelected(){const r=record(),w=$('#viewport').clientWidth,h=$('#viewport').clientHeight;project.view={x:w/2-(r.id==='vision'?700:r.x+145)*.85,y:h/2-(r.id==='vision'?350:r.y+100)*.85,z:.85};view();save();}
