function fallback(){model?.dispose();model=null;setMode('board');$('#camera-tools').hidden=true;$('#model-host').setAttribute('aria-label','Static front-view illustration. 3D unavailable. Project records remain accessible.');$('#model-host').innerHTML='<div class="fallback"><svg viewBox="0 0 240 420" aria-label="Orthographic vehicle concept"><path d="M120 20 L142 90 V340 L155 375 H85 L98 340 V90Z" fill="#bfcac7"/><path d="M98 150 L32 280 L98 250 M142 150 L208 280 L142 250" fill="#c98e62"/><path d="M98 92H142M98 305H142" stroke="#212d2e" stroke-width="5"/></svg><p>Illustrative front view<br>3D unavailable · all project records remain accessible</p></div>';$('#inspect').disabled=true;for(const id of ['pose','cutaway','explode'])$('#'+id).disabled=true;}
for(const id of ['inspect','pose','cutaway','explode'])$('#'+id).disabled=true;import('./model.js').then(({initModel})=>{model=initModel($('#model-host'),id=>select(id));model.select(selected);model.explode(true);for(const id of ['inspect','pose','cutaway','explode'])$('#'+id).disabled=false;}).catch(()=>fallback());$('#model-host').addEventListener('model-failed',fallback);
// All text comes through text escaping. Delegated actions keep the canvas keyboard-operable.
document.addEventListener('click',e=>{const s=e.target.closest('[data-select]');if(s){select(s.dataset.select);return;}const o=e.target.closest('[data-outline]');if(o){select(o.dataset.outline);focusSelected();$('#outline').hidden=true;return;}const m=e.target.closest('[data-move]');if(m){const [dx,dy]=m.dataset.move.split(',').map(Number);if(selected==='vision')return toast('The vehicle anchor stays fixed. Move the surrounding cards.');change(()=>{record().x+=dx;record().y+=dy;});}const c=e.target.closest('[data-camera]');if(c)model?.preset(c.dataset.camera);const edge=e.target.closest('[data-remove-edge]');if(edge)change(()=>project.edges=project.edges.filter(x=>x.id!==edge.dataset.removeEdge));});
$('#add').onclick=captureDialog;$('#quick-add').onclick=captureDialog;$('#connect').onclick=connectDialog;$('#outline-toggle').onclick=()=>{$('#outline').hidden=!$('#outline').hidden;if(!$('#outline').hidden)$('#search').focus();};$('#close-outline').onclick=()=>$('#outline').hidden=true;$('#search').oninput=e=>{query=e.target.value;renderOutline();};$('#board-view').onclick=()=>{setMode('board');$('#outline').hidden=true;$('#inspector').classList.remove('collapsed');};
$('#undo').onclick=()=>{if(!history.length)return;future.push(JSON.stringify(project));project=JSON.parse(history.pop());save();render();};$('#redo').onclick=()=>{if(!future.length)return;history.push(JSON.stringify(project));project=JSON.parse(future.pop());save();render();};
$('#inspect').onclick=()=>setMode(mode==='board'?'inspect':'board');$('#pose').onclick=()=>{pose=pose==='deployed'?'stowed':'deployed';model?.setPose(pose);$('#pose').textContent=pose==='deployed'?'Stow wings':'Deploy wings';$('#pose').classList.toggle('active',pose==='stowed');$('#model-host').setAttribute('aria-label',`Illustrative vehicle, wings ${pose}. Motion path unresolved.`);if(pose==='stowed'&&!cut)$('#cutaway').click();};$('#cutaway').onclick=()=>{cut=!cut;model?.cutaway(cut);$('#cutaway').classList.toggle('active',cut);$('#cutaway').setAttribute('aria-pressed',String(cut));};$('#explode').onclick=()=>{exploded=!exploded;model?.explode(exploded);$('#explode').classList.toggle('active',exploded);$('#explode').setAttribute('aria-pressed',String(exploded));$('#explode').textContent=exploded?'Assemble modules':'Separate modules';$('#pose-note').textContent=exploded?'Sectioned assembly · spacing is illustrative':'Assembled concept · deployment path unresolved';};$('#model-minus').onclick=()=>model?.zoom(1.1);$('#model-plus').onclick=()=>model?.zoom(.9);
function zoom(f){const v=project.view,w=$('#viewport').clientWidth/2,h=$('#viewport').clientHeight/2,z=Math.max(.25,Math.min(1.6,v.z*f)),scale=z/v.z;project.view={x:w-(w-v.x)*scale,y:h-(h-v.y)*scale,z};view();save();}
$('#zoom-in').onclick=()=>zoom(1.15);$('#zoom-out').onclick=()=>zoom(1/1.15);$('#focus').onclick=focusSelected;$('#fit').onclick=()=>{const maxX=Math.max(...project.records.map(r=>r.x+320)),maxY=Math.max(...project.records.map(r=>r.y+230)),w=$('#viewport').clientWidth,h=$('#viewport').clientHeight;const z=Math.max(.25,Math.min(1,(w-50)/maxX,(h-50)/maxY));project.view={x:25,y:25,z};view();save();};$('#reset-view').onclick=()=>{project.view=initialView();view();save();};$('#original').onclick=()=>{select('vision');$('#reset-view').click();$('#original').classList.add('active');$('#baseline').classList.remove('active');};$('#baseline').onclick=()=>{select('baseline');focusSelected();$('#baseline').classList.add('active');$('#original').classList.remove('active');};$('#back').onclick=()=>{if(back.length)select(back.pop(),false);};
function download(text,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}function exportFile(){download(JSON.stringify(project,null,2),'recoverable-flight-board.json','application/json');toast('Project exported. Keep this file as a recovery copy.');}
$('#save-state').onclick=()=>{if(loadBlocked){dialog('<h2>Recover your saved board.</h2><p>The saved data could not be read. It has not been overwritten. Download the original bytes for safekeeping, or start a fresh board with a recovery copy kept on this device.</p><button id="export-unreadable">Download original data</button><button id="recover-board" class="primary">Keep recovery copy & start fresh</button>');$('#export-unreadable').onclick=()=>download(unreadableRaw||'','unreadable-flight-board.txt','text/plain');$('#recover-board').onclick=()=>{try{project=recoverProject(localStorage,KEY,unreadableRaw);expected=project.revision;loadBlocked=false;unreadableRaw=null;dirty=false;storageError='';history=[];future=[];selected='wing';project.view=initialView();save();render();$('#dialog').close();toast('Fresh board saved. Original bytes retained as a recovery copy.');}catch(e){toast(e.message);}};return;}if(project.manifest!==newProject().manifest){dialog('<h2>Review the source snapshot.</h2><p>This saved board refers to an earlier bundled source snapshot. Your proposals have been preserved. Review the captured project vision and system requirements before relying on them.</p><p><a href="' + import.meta.env.BASE_URL + 'sources/USER-VISION.md" target="_blank" rel="noopener">Project vision ↗</a><br><a href="' + import.meta.env.BASE_URL + 'sources/SYSTEM-SPEC.md" target="_blank" rel="noopener">System requirements ↗</a></p><button id="ack-source" class="primary">Use current source snapshot</button>');$('#ack-source').onclick=()=>{change(()=>project.manifest=newProject().manifest);$('#dialog').close();};}else dialog('<h2>Your work stays here.</h2><p>Changes save in this browser on this device. Export a project file for a portable recovery copy. There is no cloud account or shared editing.</p><p>'+esc(storageError||'Local storage is available.')+'</p>');};$('#export').onclick=exportFile;$('#import').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2000000)return toast('Project file is too large (2 MB maximum).');try{const p=validateProject(JSON.parse(await file.text()));dialog(`<h2>Import this board?</h2><p>${p.records.length} records · ${p.edges.length} connections · ${p.story.length} story stops</p><p>This replaces the board on this device. Export your current board first if you want to keep it.</p><button id="export-before">Export current board</button><button class="primary" id="replace">Replace local board</button>`);$('#export-before').onclick=exportFile;$('#replace').onclick=()=>{try{if(loadBlocked)throw Error('Recover the unreadable saved board before importing.');const next=saveProject(localStorage,KEY,p,expected);checkpoint();project=next;expected=next.revision;selected='vision';pin=null;storageError='';dirty=false;story=-1;$('#story-bar').hidden=true;render();$('#dialog').close();toast('Imported board saved on this device.');}catch(error){toast('Import not applied. '+error.message);}};}catch(e){toast(e.message);}};
function showStory(){if(story<0)return;$('#story-bar').hidden=false;const id=project.story[story];select(id);focusSelected();$('#story-title').textContent=`${story+1} / ${project.story.length}  ·  ${displayText(record(),'title')}`;$('#story-prev').disabled=story===0;$('#story-next').disabled=story>=project.story.length-1;}
let beforeStory;$('#present').onclick=()=>{if(!project.story.length)return toast('Add a card to your story from Arrange & present.');beforeStory={view:{...project.view},selected};story=0;showStory();};$('#story-prev').onclick=()=>{story=Math.max(0,story-1);showStory();};$('#story-next').onclick=()=>{story=Math.min(project.story.length-1,story+1);showStory();};$('#story-exit').onclick=()=>{story=-1;$('#story-bar').hidden=true;if(beforeStory){project.view=beforeStory.view;select(beforeStory.selected);view();save();}};
$('#help').onclick=()=>dialog('<div class="eyebrow">WORKSPACE CONTROLS</div><h2>Canvas controls</h2><p>Drag a section heading to move its cards together. Shift-click card grips to select a custom group, then drag one selected grip. Escape clears the group. The vehicle illustration stays fixed. Drag the canvas or model background to pan. Hold Space and drag, or use the middle mouse button, to pan over cards. Two-finger scrolling pans; pinch zooms. Drag a card’s top bar to arrange it, or use its Arrange arrow buttons. Use Fit board to see everything.</p><p>Inspect 3D switches model gestures to orbit. Front, Side, Top, and zoom buttons provide alternatives. Escape returns to canvas mode.</p><p>Use the section tabs to move between vehicle, questions, experiments, directions, and sources. Connections are named relationships, not wires or a flight path. Select a card to see its lines.</p><p>Project → Download board backup saves a file containing your notes and layout. Open board file restores one. Your normal edits already save in this browser.</p><p>Every view is an illustration. No flight, simulation, or physical approval is implied.</p>');
let drag=null,spacePan=false,suppressClick=false;
function paintGroup(){document.querySelectorAll('.card').forEach(el=>el.classList.toggle('group-selected',grouped.has(el.dataset.id)));}
const viewport=$('#viewport');
const editing=e=>e.target.closest('input,textarea,select,[contenteditable="true"]');
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!editing(e)&&!e.target.closest('button,a,summary,[role="button"]')&&!$('#dialog').open){spacePan=true;viewport.classList.add('pan-ready');e.preventDefault();}});
window.addEventListener('keyup',e=>{if(e.code==='Space'){spacePan=false;viewport.classList.remove('pan-ready');}});
function finishDrag(e){if(!drag||e&&e.pointerId!==drag.pointerId)return;if(drag.moved){suppressClick=true;setTimeout(()=>suppressClick=false,0);save();$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;}const id=drag.pointerId;drag=null;viewport.classList.remove('dragging');if(viewport.hasPointerCapture(id))viewport.releasePointerCapture(id);paintGroup();}
window.addEventListener('blur',()=>{spacePan=false;viewport.classList.remove('pan-ready');finishDrag();});
viewport.addEventListener('click',e=>{if(suppressClick){e.stopImmediatePropagation();e.preventDefault();}},true);
viewport.addEventListener('pointerdown',e=>{
 if(drag||![0,1].includes(e.button)||editing(e))return;
 const forcePan=spacePan||e.button===1;
 if(!forcePan&&mode==='inspect'&&e.target.closest('#model-card'))return;
 const handle=e.target.closest('.card-handle'),section=e.target.closest('[data-drag-section]');
 if(!forcePan&&e.target.closest('button,article,[data-edge]')&&!handle&&!section)return;
 const id=handle?.dataset.select;
 if(!forcePan&&e.shiftKey&&id){e.preventDefault();grouped.has(id)?grouped.delete(id):grouped.add(id);paintGroup();return;}
 const ids=forcePan?[]:section?project.records.filter(r=>r.id!=='vision'&&sectionFor(r)===section.dataset.dragSection).map(r=>r.id):id?(grouped.has(id)?[...grouped]:[id]):[];
 drag={pointerId:e.pointerId,ids,startX:e.clientX,startY:e.clientY,x:project.view.x,y:project.view.y,positions:ids.map(id=>{const r=project.records.find(r=>r.id===id);return {id,x:r.x,y:r.y};}),moved:false};
 if(forcePan){e.preventDefault();e.stopPropagation();}
},true);
viewport.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointerId)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(!drag.moved){if(Math.hypot(dx,dy)<=4)return;if(drag.ids.length)checkpoint();drag.moved=true;viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging');}
 if(drag.ids.length){for(const start of drag.positions){const r=project.records.find(r=>r.id===start.id);r.x=start.x+dx/project.view.z;r.y=start.y+dy/project.view.z;const card=$(`[data-id="${r.id}"]`);card.style.left=r.x+'px';card.style.top=r.y+'px';}lines();}else{project.view.x=drag.x+dx;project.view.y=drag.y+dy;view();}});
window.addEventListener('pointerup',finishDrag);viewport.addEventListener('pointercancel',finishDrag);viewport.addEventListener('lostpointercapture',finishDrag);
viewport.addEventListener('wheel',e=>{if(editing(e)||mode==='inspect'&&e.target.closest('#model-card'))return;e.preventDefault();const scale=e.deltaMode===1?16:e.deltaMode===2?viewport.clientHeight:1;if(e.ctrlKey||e.metaKey){zoom(Math.exp(-e.deltaY*.01));}else{project.view.x-=e.deltaX*scale;project.view.y-=e.deltaY*scale;view();save();}},{passive:false});
document.addEventListener('keydown',e=>{const section=e.target.closest('[data-drag-section]');if(section&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const id=section.dataset.dragSection,dx=e.key==='ArrowLeft'?-30:e.key==='ArrowRight'?30:0,dy=e.key==='ArrowUp'?-30:e.key==='ArrowDown'?30:0;change(()=>{for(const r of project.records)if(r.id!=='vision'&&sectionFor(r)===id){r.x+=dx;r.y+=dy;}});$(`[data-drag-section="${id}"]`).focus();}if(e.key==='Escape'){grouped.clear();paintGroup();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#dialog').open)return;if(e.key==='Escape'){if(story>=0)$('#story-exit').click();setMode('board');$('#outline').hidden=true;}if(e.target.matches('input,textarea,select'))return;if((e.metaKey||e.ctrlKey)&&e.key==='z'){e.preventDefault();$(e.shiftKey?'#redo':'#undo').click();}if(e.target.matches('.outline-item')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();(e.key==='ArrowDown'?e.target.nextElementSibling:e.target.previousElementSibling)?.focus();}});
window.addEventListener('storage',e=>{if(e.key===KEY){storageError='Another tab changed this board. Export your copy, then reload.';status();toast(storageError);}});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
function initialView(){const w=$('#viewport').clientWidth;if(innerWidth<=800){const z=Math.min(.58,(w-8)/570);return {x:w/2-683*z,y:150,z};}const z=Math.max(.25,Math.min(.78,(w-60)/1390,($('#viewport').clientHeight-230)/870));return {x:(w-1390*z)/2,y:220,z};}
if(project.revision===0)project.view=initialView();render();model?.select(selected);status();entryDisclaimer();

const modelToolbar=$('.model-toolbar');function mobileControls(){if(innerWidth<=800){$('#viewport').append(modelToolbar);modelToolbar.classList.add('mobile-model-controls');}else{$('#model-card').append(modelToolbar);modelToolbar.classList.remove('mobile-model-controls');}}mobileControls();window.addEventListener('resize',mobileControls);

$('#story-edit').onclick=()=>{
 let draft=[...project.story];
 dialog('<div class="eyebrow">REVIEW SEQUENCE</div><h2>Presentation sequence</h2><p>Choose up to five stops. Each follows the current record, so edits stay in sync.</p><div id="story-editor"></div><button id="save-story" class="primary">Save story order</button>');
 function draw(){
  $('#story-editor').innerHTML=draft.map((id,i)=>`<div class="story-editor-row"><span class="story-number">0${i+1}</span><span>${esc(displayText(project.records.find(r=>r.id===id),'title'))}</span><button data-story-up="${i}" ${i===0?'disabled':''} aria-label="Move stop ${i+1} up">↑</button><button data-story-down="${i}" ${i===draft.length-1?'disabled':''} aria-label="Move stop ${i+1} down">↓</button><button data-story-remove="${i}" aria-label="Remove stop ${i+1}">×</button></div>`).join('')+`<label class="story-add-label">Add a stop<select id="story-choice" ${draft.length===5?'disabled':''}>${project.records.filter(r=>!draft.includes(r.id)).map(r=>`<option value="${esc(r.id)}">${esc(displayText(r,'title'))}</option>`).join('')}</select></label><button id="insert-stop" ${draft.length===5?'disabled':''}>＋ Add stop</button>`;
  $('#insert-stop').onclick=()=>{if(draft.length<5){draft.push($('#story-choice').value);draw();$('#insert-stop').focus();}};
  $('#story-editor').querySelectorAll('[data-story-up],[data-story-down],[data-story-remove]').forEach(b=>b.onclick=()=>{let index;if(b.dataset.storyRemove!==undefined){index=Number(b.dataset.storyRemove);draft.splice(index,1);}else{index=Number(b.dataset.storyUp??b.dataset.storyDown);const next=index+(b.dataset.storyUp!==undefined?-1:1);[draft[index],draft[next]]=[draft[next],draft[index]];index=next;}draw();$('#story-editor').querySelectorAll('.story-editor-row button')[Math.max(0,index)*3]?.focus();});
 }
 draw();$('#save-story').onclick=()=>{change(()=>project.story=draft);$('#dialog').close();toast('Story order saved.');};
};
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-source-reader]');if(!button)return;
 const r=project.records.find(r=>r.id===button.dataset.sourceReader);
 if(!r||!['/sources/USER-VISION.md','/sources/SYSTEM-SPEC.md'].includes(r.url))return;
 dialog(`<div class="eyebrow">SOURCE DOCUMENT</div><h2>${esc(displayText(r,'title'))}</h2><div id="source-document" class="source-document" aria-live="polite">Loading source…</div>`);
 const destination=$('#source-document');
 try{const response=await fetch(import.meta.env.BASE_URL+r.url.slice(1));if(!response.ok)throw Error('The source document could not be loaded.');const text=await response.text();if(text.length>100000)throw Error('This document is too large to preview.');destination.textContent=text;}catch(error){destination.textContent=error.message;}
});

