$('#model-host').insertAdjacentHTML('afterend','<div id="model-hover" aria-live="polite">Hover a module · click to open its record</div>');
$('#model-host').addEventListener('module-hover',e=>{$('#model-hover').textContent=e.detail||'Hover a module · click to open its record';});

$('#contribute').onclick=()=>dialog('<div class="eyebrow">TWO WAYS TO CONTRIBUTE</div><h2>Keep a note, or send it for review.</h2><div class="route-choice"><h3>Just for you</h3><p>Add or edit a proposal on this board. It saves only in this browser. Project → Download board backup makes a portable copy.</p><button id="local-note">Add a local note</button></div><div class="route-choice"><h3>For the public project</h3><p>Use a GitHub form. Your post is public and maintainers review it before anything becomes part of the board.</p><p><a class="contribution-link" href="https://github.com/onionviolet/recoverable-flight-lab/issues/new?template=question.yml" target="_blank" rel="noopener">Submit a question ↗</a> <a class="contribution-link" href="https://github.com/onionviolet/recoverable-flight-lab/issues/new?template=idea.yml" target="_blank" rel="noopener">Propose an idea ↗</a></p><p><a href="https://github.com/onionviolet/recoverable-flight-lab/issues" target="_blank" rel="noopener">Read public discussions ↗</a></p></div><p>Your local notes and backup are never attached to a GitHub post automatically.</p>');
$('#contribute').addEventListener('click',()=>{$('#local-note').onclick=captureDialog;});

$('#start-here').onclick=()=>dialog('<div class="eyebrow">THE WHOLE PROJECT</div><h2>Build something ambitious, test it honestly, and recover the hardware.</h2><p>C4 is the original integrated idea: a modular vehicle with internal folding wings, instruments, propulsion, and recoverable pieces. The model shows how that aspiration fits together. It is an illustration, not CAD, a simulation, or a chosen design.</p><p>Most of the engineering is still undecided: what each piece does after separation, whether the mechanism fits, which propulsion architecture applies, and what evidence would justify integration. The clearest worked trail starts with the folding-wing module and follows one unknown to a possible answer, an unperformed test, a draft decision, and the evidence gap.</p><div class="guide-actions"><button id="guide-vehicle" class="primary">Start with the modules →</button><button id="guide-evidence">See what evidence exists</button></div><p class="small-print">C0, C1, and C2 are proposed smaller development articles. They do not replace C4 unless the team reviews and accepts that direction.</p>');
$('#start-here').addEventListener('click',()=>{$('#guide-vehicle').onclick=()=>{$('#dialog').close();select('vision');showSection('vehicle');};$('#guide-evidence').onclick=()=>{$('#dialog').close();select('evidence');focusSelected();};});
